package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TarArchiveOutputStream_putArchiveEntry_TriageGen0Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOutputStream;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        tarOutputStream = new TarArchiveOutputStream(out);
    }

    @Test
    public void testPutArchiveEntry_RegularFile() throws IOException {
        String name = "test.txt";
        long size = 10L;
        TarArchiveEntry entry = new TarArchiveEntry(name);
        entry.setSize(size);

        tarOutputStream.putArchiveEntry(entry);

        // Verify state changes
        // Note: Since we cannot easily access private fields without reflection, 
        // we verify the side effect: the stream should have written the header.
        Assert.assertTrue(out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_Directory() throws IOException {
        String name = "test_dir";
        TarArchiveEntry entry = new TarArchiveEntry(name);
        entry.setDirectory(true);

        tarOutputStream.putArchiveEntry(entry);

        Assert.assertTrue(out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_LongFileMode_GNU() throws IOException {
        // Setup long file mode to GNU
        tarOutputStream.setLongFileMode(TarArchiveConstants.LONGFILE_GNU);

        // Create a name that is likely to trigger long file logic in a real scenario, 
        // but here we just need to trigger the branch.
        String longName = "this_is_a_very_long_filename_that_exceeds_the_standard_tar_limit_of_100_characters_to_test_gnu_mode_logic_properly.txt";
        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(5L);

        tarOutputStream.putArchiveEntry(entry);

        Assert.assertTrue(out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_LongFileMode_Truncate() throws IOException {
        tarOutputStream.setLongFileMode(TarArchiveConstants.LONGFILE_TRUNCATE);

        String name = "truncate_test.txt";
        TarArchiveEntry entry = new TarArchiveEntry(name);
        entry.setSize(5L);

        tarOutputStream.putArchiveEntry(entry);

        Assert.assertTrue(out.size() > 0);
    }

    @Test(expected = RuntimeException.class)
    public void testPutArchiveEntry_ThrowsExceptionWhenTooLongAndNotGNUOrTruncate() throws IOException {
        // Default mode is usually NOT GNU or TRUNCATE for long files (it's usually an error or handled differently)
        // We force a mode that is neither GNU nor TRUNCATE to trigger the RuntimeException
        // Based on the code logic: if (longFileMode != LONGFILE_GNU && longFileMode != LONGFILE_TRUNCATE) -> throw
        // We use a value that is not GNU (1) or TRUNCATE (2). Let's use 0 or 3.
        tarOutputStream.setLongFileMode(0); 

        // We need to simulate a name that is "too long". 
        // However, the code provided doesn't actually check the length of the name against TarConstants.NAMELEN 
        // inside the 'if (true)' block unless it falls into the 'else if' branch.
        // To enter the 'else if', we must NOT be in LONGFILE_GNU.

        // Actually, looking at the provided code: the 'if (longFileMode == LONGFILE_GNU)' handles long files.
        // The 'else if (longFileMode != LONGFILE_TRUNCATE)' is the error path.
        // This logic implies that if the name is "long" (though the code provided doesn't actually check length, 
        // it just enters the branch if the mode is enabled), it throws.

        // Since the provided snippet has `if (true)`, it always enters the long file logic check.
        // To trigger the exception, we need longFileMode != GNU and longFileMode != TRUNCATE.

        TarArchiveEntry entry = new TarArchiveEntry("any_name");
        tarOutputStream.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_WithMockEntry() throws IOException {
        // Using a mock to verify specific interactions if possible, 
        // although TarArchiveEntry is a concrete class with final-like behavior in some versions.
        TarArchiveEntry entry = spy(new TarArchiveEntry("mock.txt"));
        entry.setSize(10L);

        tarOutputStream.putArchiveEntry(entry);

        verify(entry, times(1)).writeEntryHeader(any());
    }
}
